/**
 * Generates the synthetic packet, byte-for-byte reproducible: fixed key, pinned
 * timestamps, deterministic field order. `npm run generate -- --out <dir>`.
 *
 * SYNTHETIC. The private key below is published on purpose so the packet can be
 * regenerated by anyone; it is therefore worthless as a trust anchor: anyone can
 * forge replacement receipts under it. This demonstrates verification mechanics.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { createAuthReceipt, signReceipt, computeReceiptHash } from '@bolyra/receipts';
import type { SignedReceipt } from '@bolyra/receipts';
import { actionDigest, formatReason } from './digest';
import type { Action } from './digest';

export const SYNTHETIC_PRIVATE_KEY = '0x' + 'b01ab01a'.repeat(8); // PUBLIC demo key; never reuse
export const ISSUER = 'audit-log-evidence-synthetic';
export const KEY_ID = 'synthetic-k1';
export const APPROVED_AT = '2026-10-08T15:00:00.000Z';
export const EXECUTED_AT = '2026-10-08T15:00:03.000Z';

export const ACTION: Action = {
  tenant: 'org_synthetic_01',
  server: 'zendesk',
  tool: 'post_reply',
  resource: { type: 'ticket', id: 'tkt_1001' },
  arguments: {
    ticket_id: 'tkt_1001',
    body: 'Thanks for flagging this. We have reissued the refund to your original payment method; it should appear within 5 business days.',
    public: true,
  },
};

export interface Packet {
  'action.json': Action;
  'approval-receipt.json': SignedReceipt;
  'execution.json': Execution;
  'export.jsonl': AuditEvent[];
  'signer.json': SignerInfo;
  'tampered/execution-altered-args.json': Execution;
}

export interface Execution {
  action: Action;
  action_digest: string;
  receipt_id: string;
  executed_at: string;
  status: number;
  note: string;
}

export interface AuditEvent {
  action: string;
  occurred_at: string;
  version: number;
  actor: { type: string; id: string; name: string };
  targets: { type: string; id: string; name?: string }[];
  context: { location: string; user_agent: string };
  metadata: Record<string, string>;
}

export interface SignerInfo {
  signer: string;
  issuer: string;
  keyId: string;
  alg: 'ES256K';
  synthetic: true;
  private_key_published: string;
  warning: string;
}

export function buildPacket(): Packet {
  const digest = actionDigest(ACTION);
  const payload = createAuthReceipt(
    {
      rootDid: 'did:bolyra:dev:synthetic-support-agent',
      actingDid: 'did:bolyra:dev:synthetic-support-agent',
      credentialCommitment: '1',
      effectiveCommitment: '1',
      allowed: true,
      reasonCode: formatReason(digest, ACTION),
      score: 100,
      permissionBitmask: '2',
      chainDepth: 0,
      humanProof: { proof: {} },
      agentProof: { proof: {} },
      humanPublicSignals: [],
      agentPublicSignals: [],
      bundleVersion: 1,
      nonce: '1',
    },
    { issuer: ISSUER, keyId: KEY_ID, issuedAt: Math.floor(Date.parse(APPROVED_AT) / 1000) },
  );
  const receipt = signReceipt(payload, { issuer: ISSUER, keyId: KEY_ID, privateKey: SYNTHETIC_PRIVATE_KEY });
  const receiptHash = computeReceiptHash(receipt);
  const signer = receipt.signature.signer;

  const targets = [
    { type: 'tool', id: `${ACTION.server}.${ACTION.tool}` },
    { type: ACTION.resource.type, id: ACTION.resource.id },
    { type: 'organization', id: ACTION.tenant },
  ];
  const events: AuditEvent[] = [
    {
      action: 'tool.approval_resolved',
      occurred_at: APPROVED_AT,
      version: 1,
      actor: { type: 'user', id: 'user_approver_01', name: 'Synthetic Approver' },
      targets,
      context: { location: '203.0.113.10', user_agent: 'synthetic/1.0' },
      metadata: { decision: 'approved', action_digest: digest, receipt_id: receipt.id, receipt_hash: receiptHash, signer },
    },
    {
      action: 'tool.executed',
      occurred_at: EXECUTED_AT,
      version: 1,
      actor: { type: 'agent', id: 'agent_support_01', name: 'Synthetic Support Agent' },
      targets,
      context: { location: 'internal', user_agent: 'synthetic-agent/1.0' },
      metadata: { action_digest: digest, receipt_id: receipt.id, receipt_hash: receiptHash, status: '200' },
    },
  ];
  const execution: Execution = {
    action: ACTION,
    action_digest: digest,
    receipt_id: receipt.id,
    executed_at: EXECUTED_AT,
    status: 200,
    note: 'unsigned host assertion; execution at the endpoint is not proven by anything in this packet',
  };
  const altered: Execution = {
    ...execution,
    action: { ...ACTION, arguments: { ...ACTION.arguments, body: 'Thanks for flagging this. We have reissued the refund of $2,400 to your original payment method.' } },
    note: 'TAMPERED: the reply body differs from the approved one; action_digest below is the ORIGINAL digest the host claims',
  };
  const signerInfo: SignerInfo = {
    signer,
    issuer: ISSUER,
    keyId: KEY_ID,
    alg: 'ES256K',
    synthetic: true,
    private_key_published: SYNTHETIC_PRIVATE_KEY,
    warning: 'Synthetic and public. Anyone can forge receipts under this key. Compare, never anchor.',
  };
  return {
    'action.json': ACTION,
    'approval-receipt.json': receipt,
    'execution.json': execution,
    'export.jsonl': events,
    'signer.json': signerInfo,
    'tampered/execution-altered-args.json': altered,
  };
}

export function serialize(packet: Packet): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(packet)) {
    out[name] = name.endsWith('.jsonl') ? (value as AuditEvent[]).map((e) => JSON.stringify(e)).join('\n') + '\n' : JSON.stringify(value, null, 2) + '\n';
  }
  return out;
}

export function writePacket(dir: string): string[] {
  const files = serialize(buildPacket());
  fs.mkdirSync(path.join(dir, 'tampered'), { recursive: true });
  for (const [name, text] of Object.entries(files)) fs.writeFileSync(path.join(dir, name), text);
  return Object.keys(files);
}

if (require.main === module) {
  const i = process.argv.indexOf('--out');
  const dir = i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : path.join(__dirname, '..', '..', 'fixtures');
  for (const f of writePacket(dir)) process.stdout.write(`wrote ${path.join(dir, f)}\n`);
}
